Running command: cd /workspace && cat > /workspace/test_fuzzer3.cc << 'EOF'
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include "allheaders.h"

static void send_to_devnull(const char *) {}
static void leptSetStdNullHandler() { leptSetStderrHandler(send_to_devnull); }

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 1; }
    FILE *f = fopen(argv[1], "rb");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<uint8_t> data(sz);
    fread(data.data(), 1, sz, f);
    fclose(f);

    BOX *box;
    PIX *pixs, *pixd;
    PIX *pix1, *pix2, *pix3, *pix4, *pix5, *pix6, *pix7, *pix8;
    PIXCMAP *cmap;

    leptSetStdNullHandler();
    pixs = pixReadMemSpix(data.data(), data.size());
    if(pixs==NULL) { fprintf(stderr, "pixs NULL\n"); return 0; }
    int w,h,d;

    pix1 = pixThresholdTo4bpp(pixs, 6, 1);
    box = boxCreate(120, 30, 200, 200);
    pixColorGray(pix1, box, L_PAINT_DARK, 220, 0, 0, 255);
    boxDestroy(&box);

    pix2 = pixScale(pix1, 1.5, 1.5);

    cmap = pixGetColormap(pix1);
    pix3 = pixOctcubeQuantFromCmap(pix2, cmap, 4, 3, L_EUCLIDEAN_DISTANCE);

    pix4 = pixConvertTo32(pix3);
    pixGetDimensions(pix4, &w, &h, &d);
    fprintf(stderr, "pix4: %dx%d depth=%d\n", w, h, d);

    PIX *pixc_test = pixFewColorsOctcubeQuant1(pix4, 3);
    if (pixc_test) {
        pixGetDimensions(pixc_test, &w, &h, &d);
        fprintf(stderr, "pixc before ops: %dx%d depth=%d\n", w, h, d);
        PIXCMAP *cc = pixGetColormap(pixc_test);
        if (cc) fprintf(stderr, "  cmap count: %d\n", pixcmapGetCount(cc));
        pixDestroy(&pixc_test);
    }

    pix5 = pixMedianCutQuant(pix4, 0);
    pix6 = pixFewColorsMedianCutQuantMixed(pix4, 30, 30, 100, 0, 0, 0);
    pixd = pixDeskew(pixs, 0);
    pixOctreeQuantByPopulation(pixs, 0, 0);

    pixc_test = pixFewColorsOctcubeQuant1(pix4, 3);
    if (pixc_test) {
        pixGetDimensions(pixc_test, &w, &h, &d);
        fprintf(stderr, "pixc after ops: %dx%d depth=%d\n", w, h, d);
        PIXCMAP *cc = pixGetColormap(pixc_test);
        if (cc) fprintf(stderr, "  cmap count: %d\n", pixcmapGetCount(cc));
        pixDestroy(&pixc_test);
    }

    pix7 = pixFewColorsOctcubeQuantMixed(pix4, 3, 20, 244, 20, 0.05, 15);
    pix8 = pixColorSegment(pixs, 50, 6, 6, 6, 0);

    pixDestroy(&pix1);
    pixDestroy(&pix2);
    pixDestroy(&pix3);
    pixDestroy(&pix4);
    pixDestroy(&pix5);
    pixDestroy(&pix6);
    pixDestroy(&pix7);
    pixDestroy(&pix8);
    pixDestroy(&pixd);
    pixDestroy(&pixs);
    return 0;
}
EOF
g++ -std=c++11 -g -fsanitize=address -no-pie -I/workspace/repo-vul/work-vul/include/leptonica -I/workspace/repo-vul/work-vul/include test_fuzzer3.cc -o test_fuzzer3 /workspace/repo-vul/work-vul/lib/liblept.a /workspace/repo-vul/work-vul/lib/libtiff.a /workspace/repo-vul/work-vul/lib/libwebp.a /workspace/repo-vul/work-vul/lib/libpng16.a /workspace/repo-vul/work-vul/lib/libjpeg.a /workspace/repo-vul/work-vul/lib/libjbig.a /workspace/repo-vul/work-vul/lib/libzstd.a /workspace/repo-vul/work-vul/lib/libz.a -lm -lpthread 2>&1 | head -5 && ./test_fuzzer3 /workspace/poc.spix 2>&1 | head -30

